## Why This Question Is Asked
This question tests dynamic programming intuition on a constrained path counting problem with simple transitions and boundary conditions.

## Key Concepts
- **Recurrence relation:** f(i) = f(i+1) + f(i+2) with modulo arithmetic
- **Memoization vs. tabulation:** Trade-offs between recursive top-down with caching versus iterative bottom-up approaches
- **Edge conditions:** Blocked start/end positions, single-cell arrays

## Code Example
```javascript
function countPaths(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  // Memoized DFS
  const memo = Array(n).fill(-1);
  function dfs(i) {
    if (i === n - 1) return blocked[i] ? 0 : 1;
    if (i >= n || blocked[i]) return 0;
    if (memo[i] !== -1) return memo[i];
    memo[i] = (dfs(i + 1) + dfs(i + 2)) % MOD;
    return memo[i];
  }
  return dfs(0);
}

// Bottom-up DP (O(1) space)
function countPathsDP(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  let next2 = 1, next1 = blocked[n - 1] ? 0 : 1;
  for (let i = n - 2; i >= 0; i--) {
    const curr = blocked[i] ? 0 : (next1 + next2) % MOD;
    next2 = next1;
    next1 = curr;
  }
  return next1;
}
```

## Why This Is Asked
Tests ability to combine weighted shortest paths with path counting via a DAG, a common real-world need in routing and logistics.

## Key Concepts
- Dijkstra for non-negative weights
- Shortest-path DAG construction
- Topological DP to count paths
- Time/space trade-offs and modular arithmetic

## Code Example
```javascript
// Pseudocode outline for counting shortest paths
function countShortestPaths(graph, s, t) {
  const dist = dijkstra(graph, s);
  const dag = buildShortestPathDag(graph, dist);
  const order = topologicalSort(dag);
  const ways = new Array(graph.n).fill(0);
  ways[s] = 1;
  for (const u of order) {
    for (const [v] of dag.adj[u]) {
      ways[v] = (ways[v] + ways[u]) % 1000000007;
    }
  }
  return { dist: dist[t], count: ways[t] };
}
```

